package com.aliothmoon.maafw.once;
import org.junit.Test;import static org.junit.Assert.*;import java.nio.file.*;
public class EntryDiagnosticWiringTest {
 private String s(String n)throws Exception{return Files.readString(Path.of(System.getProperty("staging.root",".."),"app/src/main/java/com/aliothmoon/maafw/once",n+".java"));}
 @Test public void diagnosticPreemptsRecoveryAndCapture()throws Exception{String r=s("CaptureSessionRuntime");int a=r.indexOf("private void currentBeforeReadOnOwner()");assertTrue(r.indexOf("entryDiagnosticOnOwner();return;",a)<r.indexOf("entryRecoveryOnOwner();return;",a));}
 @Test public void runtimeDiagnosticHasNoNavigationOrCounterRead()throws Exception{String r=s("CaptureSessionRuntime");String body=r.substring(r.indexOf("private void entryDiagnosticOnOwner()"),r.indexOf("private boolean diagnosticClean()"));for(String forbidden:new String[]{"AndroidRewardsEntryActor","AndroidUiStructureReader","ACTION_CLICK","Maa","COMMIT","anchorEntryTemplate"})assertFalse(forbidden,body.contains(forbidden));assertTrue(body.contains("Stage.ANCHOR"));assertTrue(body.contains("Stage.PREPARE_BEFORE"));assertTrue(body.contains("Stage.PREPARE_AFTER"));assertTrue(body.indexOf("Slot.RUN_1")<body.indexOf("entryMetadata=V46EntryMetadataReader.app"));}
 @Test public void onlyTokenSerializesNodeMetadata()throws Exception{String r=s("CaptureSessionRuntime");assertFalse(r.contains("protocolReport().summary("));assertTrue(r.contains("finalizeEntryDiagnosticPublication(details)"));assertTrue(r.contains("diagnosticSourceAfter&&diagnosticClean()&&entryAuthority()"));String p=s("EntryDiagnosticPublication");assertTrue(p.contains("report.started()"));assertTrue(p.contains("nodes=SUPPRESSED"));assertTrue(p.contains("report.summary(true)"));}
 @Test public void correctFreshSourceCopyAndNoActions()throws Exception{String a=s("DormantCaptureConfirmationActivity");assertFalse(a.contains("Root来源就绪；重新核对原Bing task15。"));String c=s("RootCaptureUi");c=c.substring(c.indexOf("static void entryDiagnosticChoice("),c.indexOf("static void rewardsEntryChoice("));for(String text:new String[]{"v47","10:25–12:00 UTC","11:57 UTC停止接纳","最多16条","0点击/COMMIT/导航"})assertTrue(text,c.contains(text));}
}
